// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }
    function testFuzz_property(uint256 val1, uint256 val2) public {
        vm.assume(val1 != val2);
        c.SetMinSum(val1);
        c.Initialized();
        uint256 beforeMinSum = c.MinSum();
        bool ok = false;
        try c.SetMinSum(val2) { ok = true; } catch { }
        if (ok) {
            assertTrue(c.MinSum() == beforeMinSum);
        }
    }
}
